import Link from "next/link";
import MarketplaceWorkspace from "../../components/MarketplaceWorkspace";
import EmptyState from "../../components/EmptyState";
export const instant = false;
const content:Record<string,{title:string;description:string}>={orders:{title:"Vendor orders",description:"Review orders assigned to this store, packing state, dispatch updates, tracking references and return requests."},products:{title:"Product catalogue",description:"Maintain product details, images, SKUs, variants, pricing, stock, shipping dimensions and policies. Listings require review before publication."},wallet:{title:"Wallet & settlements",description:"Review product-wise sales, the planned 7% management and 3% marketing fees, COD reconciliation, adjustments and eligible withdrawals. No balance is calculated in this frontend."},promotions:{title:"Vouchers & referrals",description:"Prepare store or product vouchers with minimum spend, expiry, usage limits, referral attribution and reward caps. Stacking rules require server-side validation."},settings:{title:"Store settings",description:"Manage store profile, contact details, logo, address, policies and account security after the backend is connected."}};
const nav=[{label:"Overview",href:"/marketplace/vendors"},{label:"Orders",href:"/marketplace/vendors/orders"},{label:"Products",href:"/marketplace/vendors/products"},{label:"Wallet",href:"/marketplace/vendors/wallet"},{label:"Vouchers & referrals",href:"/marketplace/vendors/promotions"},{label:"Settings",href:"/marketplace/vendors/settings"}];
export default async function VendorSectionPage({params}:{params:Promise<{section:string}>}){const {section}=await params;const page=content[section];if(!page)return <MarketplaceWorkspace title="Vendor workspace page not found" description="Choose a section from the vendor workspace navigation."><Link className="mp-primary" href="/marketplace/vendors">Return to vendor workspace</Link></MarketplaceWorkspace>;return <MarketplaceWorkspace title={page.title} eyebrow="VENDOR WORKSPACE" description={page.description} nav={nav.map(n=>({...n,active:n.href==="/marketplace/vendors/"+section}))}><div className="mb-6 rounded-2xl border border-[#f0e3dc] bg-[#fff0e8] p-5"><p className="text-sm font-bold text-[#9b4c3a]">Backend not connected</p><p className="mt-2 text-sm leading-6 text-[#65534b]">No invented orders, products, balances or rewards are displayed. Authentication, vendor ownership checks and secure APIs are required before data or write actions can be enabled.</p></div><EmptyState title="No live records loaded" description="Connect the secure API for this section to display records and enable actions." action={section==="products"?<Link href="/marketplace/vendors/products/new" className="mp-secondary">Open product form scaffold</Link>:undefined}/></MarketplaceWorkspace>}
